from network import ws_open, ws_close, ws_send
import json
h = ws_open('wss://localhost/echo', 'w4')
ev = {}
while ev.get('msg') != 'w4':
    ev = json.loads(receive())
ws_send(h, 'hi')
ev = {}
while ev.get('msg') != 'w4' or ev['type'] != 'message':
    ev = json.loads(receive())
ws_close(h)
render(ev['data'])

from network import ws_open, ws_close, ws_send
import json
h = ws_open('wss://localhost/echo', 'w5')
ev = {}
while ev.get('msg') != 'w5':
    ev = json.loads(receive())
ws_close(h)
ev = {}
while ev.get('msg') != 'w5' or ev['type'] != 'close':
    ev = json.loads(receive())
render(ev['type'] + ' ' + str(ev['was_clean']))
